import json
d = json.load(open('output/analysis_results.json'))
print('Valid JSON')
assert set(d) == {'eda_results','hypothesis_test_results'}
assert set(d['eda_results']) == {'sales_stats_by_region','unique_product_count'}
for r in ['Region A','Region B','Region C']:
    assert set(d['eda_results']['sales_stats_by_region'][r]) == {'mean_sales','median_sales','std_dev_sales'}
h = d['hypothesis_test_results']
assert set(h) == {'hypothesis','assumption_checks','chosen_test','test_justification','t_statistic','u_statistic','p_value','confidence_interval_lower','confidence_interval_upper','conclusion'}
assert set(h['assumption_checks']) == {'normality_shapiro_wilk_region_a_p_value','normality_shapiro_wilk_region_b_p_value','variance_homogeneity_levenes_p_value'}
print('Structure OK')
print('chosen:', h['chosen_test'], '| p:', h['p_value'], '| U:', h['u_statistic'], '| CI:', h['confidence_interval_lower'], h['confidence_interval_upper'])
""}

